use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use actix_files::Files;
use std::path::PathBuf;
use serde::Deserialize;

#[derive(Deserialize, Clone)]
struct ProxyConfig {
    trusted_proxies: Vec<String>,
    static_root: String,
    strip_prefix: String,
    enable_index: bool,
}

struct AppState {
    config: ProxyConfig,
}

fn is_trusted_proxy(req: &HttpRequest, state: &web::Data<AppState>) -> bool {
    let peer = req.peer_addr()
        .map(|a| a.ip().to_string())
        .unwrap_or_default();
    state.config.trusted_proxies.contains(&peer)
}

fn get_real_path(req: &HttpRequest, state: &web::Data<AppState>) -> String {
    // When behind reverse proxy, use X-Original-URI if available
    // Only trust this header from verified proxies
    if is_trusted_proxy(req, state) {
        if let Some(original) = req.headers().get("X-Original-URI") {
            if let Ok(uri) = original.to_str() {
                return uri.to_string();
            }
        }
    }
    req.path().to_string()
}

fn sanitize_path(path: &str) -> Option<PathBuf> {
    let decoded = urlencoding::decode(path).ok()?;
    let cleaned = decoded.replace("\\", "/");
    let path = PathBuf::from(&cleaned);

    // Reject path traversal attempts
    for component in path.components() {
        match component {
            std::path::Component::ParentDir => return None,
            std::path::Component::Normal(s) => {
                if s.to_string_lossy().contains(".."){ return None; }
            }
            _ => {}
        }
    }
    Some(path)
}

/// Determines if directory listing should be shown based on proxy headers
/// The reverse proxy sets X-Directory-Listing: deny for public-facing requests
/// Internal requests from trusted proxies may override this
fn should_show_listing(req: &HttpRequest, state: &web::Data<AppState>) -> bool {
    let base_policy = state.config.enable_index;

    // Only process directory listing headers from trusted proxies
    if !is_trusted_proxy(req, state) {
        // Direct access without going through proxy - deny listing always
        return false;
    }

    // Check if proxy explicitly denies listing
    if let Some(policy) = req.headers().get("X-Directory-Listing") {
        if let Ok(val) = policy.to_str() {
            if val == "deny" {
                return false;
            }
            if val == "allow" {
                return true;
            }
        }
    }

    // Trusted proxy without explicit header (e.g., health-check paths)
    // Default to deny for safety
    false
}

async fn serve_static(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let path_str = get_real_path(&req, &state);

    let stripped = path_str.strip_prefix(&state.config.strip_prefix)
        .unwrap_or(&path_str);

    let sanitized = match sanitize_path(stripped) {
        Some(p) => p,
        None => return HttpResponse::BadRequest().body("Invalid path"),
    };

    let full_path = PathBuf::from(&state.config.static_root).join(&sanitized);

    // Verify the resolved path is still under static_root
    let canonical_root = match std::fs::canonicalize(&state.config.static_root) {
        Ok(p) => p,
        Err(_) => return HttpResponse::InternalServerError().finish(),
    };
    if full_path.is_file() || full_path.is_dir() {
        let canonical_full = match std::fs::canonicalize(&full_path) {
            Ok(p) => p,
            Err(_) => return HttpResponse::NotFound().finish(),
        };
        if !canonical_full.starts_with(&canonical_root) {
            return HttpResponse::Forbidden().body("Access denied");
        }
    }

    if full_path.is_file() {
        match std::fs::read(&full_path) {
            Ok(contents) => {
                let mime = mime_guess::from_path(&full_path)
                    .first_or_octet_stream();
                HttpResponse::Ok()
                    .content_type(mime.as_ref())
                    .body(contents)
            }
            Err(_) => HttpResponse::InternalServerError().finish(),
        }
    } else if full_path.is_dir() {
        // Check index.html first
        let index = full_path.join("index.html");
        if index.is_file() {
            match std::fs::read(&index) {
                Ok(contents) => {
                    return HttpResponse::Ok()
                        .content_type("text/html")
                        .body(contents);
                }
                Err(_) => return HttpResponse::InternalServerError().finish(),
            }
        }

        if should_show_listing(&req, &state) {
            // Generate directory listing
            let mut listing = String::from("<html><body><h1>Index</h1><ul>");
            if let Ok(entries) = std::fs::read_dir(&full_path) {
                for entry in entries.flatten() {
                    let name = entry.file_name().to_string_lossy().to_string();
                    let escaped_name = html_escape(&name);
                    listing.push_str(&format!("<li><a href=\"{}\">{}</a></li>", escaped_name, escaped_name));
                }
            }
            listing.push_str("</ul></body></html>");
            HttpResponse::Ok()
                .content_type("text/html")
                .body(listing)
        } else {
            HttpResponse::Forbidden().body("Directory listing denied")
        }
    } else {
        HttpResponse::NotFound().finish()
    }
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
     .replace('<', "&lt;")
     .replace('>', "&gt;")
     .replace('"', "&quot;")
     .replace('\'', "&#x27;")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let config = ProxyConfig {
        trusted_proxies: vec!["127.0.0.1".to_string(), "10.0.0.1".to_string()],
        static_root: "/var/www/static".to_string(),
        strip_prefix: "/assets".to_string(),
        enable_index: true,
    };

    let state = web::Data::new(AppState { config });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .default_service(web::route().to(serve_static))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
